// Dispatch IDE's default settings (design/douyin-inspiration 5A.2, 5A.3): themes/ide-defaults.json,
// generated by app/scripts/gen-ide-theme.mjs. Written into the user settings once per `version`,
// only for keys the user has not set; the theme keys go in together, and only when none is set.

export interface IdeDefaults {
  version: number;
  theme: Record<string, unknown>;
  settings: Record<string, unknown>;
  /** extra settings for the Agents window's own profile only (chat.disableAIFeatures off there, not in the editor) */
  agents?: Record<string, unknown>;
  /** earlier defaults this version replaces: written over when the user's value is still the old default */
  replaces?: Record<string, unknown>;
}

/** The user's own value for a key (VS Code's inspect().globalValue), undefined when not set. */
export type UserValue = (key: string) => unknown;

/** [key, value] pairs to write now; empty once this version has been applied. */
export function defaultsToWrite(d: IdeDefaults, userValue: UserValue, appliedVersion: number, agentsWindow = false): [string, unknown][] {
  if (!d || appliedVersion >= d.version) return [];
  const out: [string, unknown][] = [];
  const theme = Object.entries(d.theme || {});
  if (theme.length && theme.every(([k]) => userValue(k) === undefined)) out.push(...theme);
  const settings = { ...d.settings, ...(agentsWindow ? d.agents : undefined) };
  const replaces = d.replaces || {};
  for (const [k, v] of Object.entries(settings)) {
    const mine = userValue(k);
    if (mine === undefined || (k in replaces && mine === replaces[k] && mine !== v)) out.push([k, v]);
  }
  return out;
}
